 'new-stock':()=>modal('Novo produto',`<div class="form-grid"><div class="field full"><label>Nome do produto *</label><input id="eNome" data-trim autocomplete="off" placeholder="Ex.: Shampoo neutro 500 ml"></div><div class="field"><label>EAN / Código de barras</label><input id="eEan" data-mask="ean" inputmode="numeric" maxlength="14" autocomplete="off" placeholder="8, 12, 13 ou 14 dígitos"></div><div class="field"><label>Marca</label><input id="eMarca" data-trim placeholder="Ex.: Pet Society"></div><div class="field"><label>Categoria</label><input id="eCategoria" data-trim placeholder="Ex.: Higiene"></div><div class="field"><label>Unidade</label><select id="eUnidade"><option>unidade</option><option>kg</option><option>litro</option><option>caixa</option><option>pacote</option></select></div><div class="field"><label>Quantidade</label><input id="eQtd" type="number" min="0" step="1" inputmode="numeric" value="0"></div><div class="field"><label>Estoque mínimo</label><input id="eMin" type="number" min="0" step="1" inputmode="numeric" value="${Number(db.data.config.estoqueMinimoPadrao??3)}"></div><div class="field"><label>Custo unitário</label><input id="eCusto" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0,00"></div><div class="field full"><label>Preço de venda</label><input id="eVenda" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0,00"></div></div>`,close=>{const nome=$('#eNome').value.trim(),ean=onlyDigits($('#eEan').value);if(!nome)return toast('Informe o produto.');if(!validEan(ean))return toast('O EAN deve possuir 8, 12, 13 ou 14 dígitos.');if(ean&&db.data.estoque.some(p=>onlyDigits(p.ean)===ean))return toast('Já existe um produto cadastrado com este EAN.');db.data.estoque.push({id:uid(),nome,ean,marca:$('#eMarca').value.trim(),categoria:$('#eCategoria').value.trim(),unidade:$('#eUnidade').value,qtd:Number($('#eQtd').value||0),min:Number($('#eMin').value||0),custo:Number($('#eCusto').value||0),valorVenda:Number($('#eVenda').value||0)});db.save();close();toast('Produto cadastrado.');}),
 'finish-appointment':b=>{const a=db.data.agenda.find(x=>x.id===b.dataset.id);if(a){if(a.status==='Concluído')return toast('Este atendimento já foi finalizado.');a.status='Concluído';const serv=db.data.servicos.find(x=>x.id===a.servicoId),pet=db.data.pets.find(p=>p.id===a.petId),cliente=db.data.clientes.find(c=>c.id===pet?.clienteId),valor=Number(serv?.valor||0);db.data.pendencias.push({id:uid(),agendaId:a.id,data:today(),pet:pet?.nome||'Pet',tutor:cliente?.nome||'Tutor',clienteId:cliente?.id||'',servico:serv?.nome||'Serviço',valor,status:'aberto'});db.save();toast('Atendimento concluído. O valor ficou em aberto no Caixa.');}},
 'delete-client':b=>{db.data.clientes=db.data.clientes.filter(x=>x.id!==b.dataset.id);const petIds=db.data.pets.filter(p=>p.clienteId===b.dataset.id).map(p=>p.id);db.data.pets=db.data.pets.filter(p=>p.clienteId!==b.dataset.id);db.data.agenda=db.data.agenda.filter(a=>!petIds.includes(a.petId));db.save();toast('Cliente excluído.');},
