 'receive-service':b=>{const item=db.data.pendencias.find(x=>x.id===b.dataset.id);if(!item)return;const cliente=db.data.clientes.find(c=>c.id===item.clienteId),cash=Number(cliente?.cashback||0),coupons=cliente&&hasFeature('cupons')?validClientCoupons(cliente.id):[];modal('Receber atendimento',`<div class="form-grid"><div class="field full"><label>Atendimento</label><input value="${escapeAttr(item.pet+' · '+item.servico)}" disabled></div><div class="field"><label>Valor</label><input id="recValor" type="number" min="0" step="0.01" value="${Number(item.valor||0)}"></div><div class="field"><label>Forma de pagamento</label><select id="recForma"><option>PIX</option><option>Dinheiro</option><option>Cartão de débito</option><option>Cartão de crédito</option><option>Outro</option></select></div>${cliente&&hasFeature('cashback')?`<div class="field"><label>Usar cashback (disponível ${money(cash)})</label><input id="recCashback" type="number" min="0" max="${cash}" step="0.01" value="0"></div>`:''}${coupons.length?`<div class="field"><label>Cupom</label><select id="recCupom"><option value="">Nenhum</option>${coupons.map(c=>`<option value="${c.id}">${c.codigo} · ${c.tipo==='percentual'?c.valor+'%':money(c.valor)}</option>`).join('')}</select></div>`:''}</div>`,close=>{let bruto=Number($('#recValor').value||0),cashUse=Math.min(Number($('#recCashback')?.value||0),cash,bruto),discount=0,coupon=db.data.cupons.find(c=>c.id===$('#recCupom')?.value);if(coupon)discount=coupon.tipo==='percentual'?bruto*Number(coupon.valor)/100:Number(coupon.valor);discount=Math.min(discount,bruto-cashUse);const valor=Math.max(0,bruto-cashUse-discount),forma=$('#recForma').value;item.status='pago';item.paidAt=new Date().toISOString();item.forma=forma;item.valorBruto=bruto;item.cashbackUsado=cashUse;item.descontoCupom=discount;db.data.caixa.push({id:uid(),tipo:'entrada',data:today(),descricao:`Atendimento: ${item.servico} — ${item.pet}`,valor,valorBruto:bruto,cashbackUsado:cashUse,desconto:discount,forma,pendenciaId:item.id});if(cliente){if(cashUse){cliente.cashback=Math.max(0,cash-cashUse);addLoyaltyHistory(cliente.id,'cashback_usado','Cashback usado no atendimento',-cashUse,{pendenciaId:item.id});}if(coupon){coupon.status='usado';coupon.usedAt=new Date().toISOString();addLoyaltyHistory(cliente.id,'cupom_usado',`Cupom ${coupon.codigo} utilizado`,-discount,{cupomId:coupon.id});}if(hasFeature('fidelidade')){const pontos=Math.floor(valor*Number(db.data.config.pontosPorReal||1));cliente.pontos=Number(cliente.pontos||0)+pontos;addLoyaltyHistory(cliente.id,'pontos_ganhos','Pontos do atendimento',pontos,{pendenciaId:item.id});if(hasFeature('cashback')){const cb=valor*Number(db.data.config.percentualCashback||0)/100;cliente.cashback=Number(cliente.cashback||0)+cb;addLoyaltyHistory(cliente.id,'cashback_gerado','Cashback do atendimento',cb,{pendenciaId:item.id});}}}runPremiumAutomations();db.save();close();toast(`Pagamento recebido: ${money(valor)}.`);},'Confirmar recebimento');},
