 'adjust-loyalty':b=>{const c=db.data.clientes.find(x=>x.id===b.dataset.id);if(!c)return;modal(`Ajustar fidelidade · ${c.nome}`,`<div class="form-grid"><div class="field"><label>Total de pontos</label><input id="loyaltyPoints" type="number" min="0" value="${Number(c.pontos||0)}"></div><div class="field"><label>Cashback disponível</label><input id="loyaltyCashback" type="number" min="0" step="0.01" value="${Number(c.cashback||0).toFixed(2)}"></div><div class="field full"><label>Motivo do ajuste</label><input id="loyaltyReason" placeholder="Ex.: correção de saldo, campanha, cortesia"></div></div>`,close=>{const oldP=Number(c.pontos||0),oldC=Number(c.cashback||0),newP=Math.max(0,Number($('#loyaltyPoints').value||0)),newC=Math.max(0,Number($('#loyaltyCashback').value||0)),reason=$('#loyaltyReason').value.trim()||'Ajuste manual';c.pontos=newP;c.cashback=newC;if(newP!==oldP)addLoyaltyHistory(c.id,'ajuste_pontos',reason,newP-oldP);if(newC!==oldC)addLoyaltyHistory(c.id,'ajuste_cashback',reason,newC-oldC);runPremiumAutomations();db.save();close();toast('Saldos de fidelidade atualizados.');});},
 'redeem-reward':b=>{const c=db.data.clientes.find(x=>x.id===b.dataset.id);if(!c)return;const available=db.data.recompensas.filter(r=>r.ativo!==false&&Number(c.pontos||0)>=Number(r.pontos||0));modal(`Resgatar recompensa · ${c.nome}`,available.length?`<div class="reward-choice">${available.map(r=>`<label><input type="radio" name="rewardChoice" value="${r.id}"><span><b>${escapeHtml(r.nome)}</b><small>${r.pontos} pontos · ${money(r.valor)} de crédito</small></span></label>`).join('')}</div>`:'<div class="empty">O tutor ainda não possui pontos suficientes.</div>',close=>{const id=document.querySelector('[name=rewardChoice]:checked')?.value;if(!id)return toast('Selecione uma recompensa.');const r=db.data.recompensas.find(x=>x.id===id);c.pontos=Number(c.pontos||0)-Number(r.pontos);c.cashback=Number(c.cashback||0)+Number(r.valor||0);addLoyaltyHistory(c.id,'pontos_resgatados',`Recompensa: ${r.nome}`,-Number(r.pontos),{recompensaId:r.id});addLoyaltyHistory(c.id,'cashback_gerado',`Crédito da recompensa: ${r.nome}`,Number(r.valor),{recompensaId:r.id});db.save();close();toast('Recompensa resgatada e convertida em crédito.');},'Resgatar');},
 'new-reward':()=>modal('Nova recompensa',`<div class="form-grid"><div class="field full"><label>Nome</label><input id="rewardName"></div><div class="field"><label>Pontos necessários</label><input id="rewardPoints" type="number" min="1"></div><div class="field"><label>Valor do benefício</label><input id="rewardValue" type="number" min="0" step="0.01"></div></div>`,close=>{if(!$('#rewardName').value.trim()||Number($('#rewardPoints').value)<=0)return toast('Preencha nome e pontos.');db.data.recompensas.push({id:uid(),nome:$('#rewardName').value.trim(),pontos:Number($('#rewardPoints').value),valor:Number($('#rewardValue').value||0),ativo:true});db.save();close();toast('Recompensa criada.');}),
 'new-coupon':()=>{if(!hasFeature('cupons'))return;modal('Criar cupom',`<div class="form-grid"><div class="field"><label>Cliente</label><select id="couponClient"><option value="">Cupom geral</option>${db.data.clientes.map(c=>`<option value="${c.id}">${c.nome}</option>`).join('')}</select></div><div class="field"><label>Código</label><input id="couponCode" value="PROMO${Math.floor(Math.random()*900+100)}"></div><div class="field"><label>Tipo</label><select id="couponType"><option value="percentual">Percentual</option><option value="valor">Valor em reais</option></select></div><div class="field"><label>Desconto</label><input id="couponValue" type="number" min="0" step="0.01" value="10"></div><div class="field"><label>Validade</label><input id="couponExpiry" type="date" value="${daysFromNow(30)}"></div></div>`,close=>{const code=$('#couponCode').value.trim().toUpperCase();if(!code)return toast('Informe o código.');db.data.cupons.push({id:uid(),codigo:code,clienteId:$('#couponClient').value,tipo:$('#couponType').value,valor:Number($('#couponValue').value||0),validade:$('#couponExpiry').value,status:'ativo',origem:'Manual',createdAt:new Date().toISOString()});db.save();close();toast('Cupom criado.');});},
 'send-campaign':b=>{const x=db.data.campanhas.find(c=>c.id===b.dataset.id),c=x&&db.data.clientes.find(c=>c.id===x.clienteId);if(!x||!c)return;if(!c.telefone)return toast('O tutor não possui WhatsApp cadastrado.');window.open(`https://wa.me/55${onlyDigits(c.telefone)}?text=${encodeURIComponent(x.mensagem)}`,'_blank');x.status='enviada';x.sentAt=new Date().toISOString();db.save();toast('Campanha marcada como enviada.');},
 'report-period':b=>{const n=Number(b.dataset.days||30);reportEnd=today();reportStart=daysAgo(n-1);render();},
 'report-month':()=>{const d=new Date();reportStart=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;reportEnd=today();render();},
 'apply-report-period':()=>{const start=$('#reportStart').value,end=$('#reportEnd').value;if(!start||!end)return toast('Selecione a data inicial e final.');if(start>end)return toast('A data inicial não pode ser maior que a final.');reportStart=start;reportEnd=end;render();toast('Relatório atualizado.');},
